-- Reference schema. The running application creates equivalent tables through SQLAlchemy.
CREATE TABLE user_account (id SERIAL PRIMARY KEY, email VARCHAR(255) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL, name VARCHAR(120) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE store (id SERIAL PRIMARY KEY, seller_id INTEGER UNIQUE NOT NULL REFERENCES user_account(id), name VARCHAR(160) NOT NULL, description TEXT, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE product (id SERIAL PRIMARY KEY, store_id INTEGER NOT NULL REFERENCES store(id), name VARCHAR(200) NOT NULL, description TEXT, price_cents INTEGER NOT NULL CHECK (price_cents >= 0), inventory INTEGER NOT NULL CHECK (inventory >= 0), image_path VARCHAR(255), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE orders (id SERIAL PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES user_account(id), status VARCHAR(30) NOT NULL, subtotal_cents INTEGER NOT NULL, shipping_cents INTEGER NOT NULL, tax_cents INTEGER NOT NULL, total_cents INTEGER NOT NULL, shipping_address TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
